# Generated by the gotry-io/nett release workflow from packaging/homebrew/nett.rb, which fills in the
# version and the sha256 of both archives. Change the template there, not this file.
class Nett < Formula
  desc "Self-hosted mesh network for your own machines"
  homepage "https://github.com/gotry-io/nett"
  version "0.3.4"
  license any_of: ["MIT", "Apache-2.0"]

  on_arm do
    url "https://github.com/gotry-io/nett/releases/download/v0.3.4/nett-0.3.4-aarch64-apple-darwin.tar.gz"
    sha256 "05076244598ee8189fe972eb885ddcb618c5eaeab7524a09496201c0e1132a23"
  end
  on_intel do
    url "https://github.com/gotry-io/nett/releases/download/v0.3.4/nett-0.3.4-x86_64-apple-darwin.tar.gz"
    sha256 "5fff191fb174b0fdcf432363ef1fdfa6570a7f4d7e8066d52cc5e902a0a95aca"
  end

  depends_on :macos

  def install
    bin.install "nett"
  end

  def caveats
    <<~EOS
      To join the mesh as a native member (root is needed for the utun interface):
        sudo nett install                          # prints this machine's keys
        nett site add <name> --keys "<that line>"  # in the site, ~/.config/nett by default
        sudo nett install                          # finds this machine's desired state and starts the service
      Run `sudo nett install` again after the site changes and after `brew upgrade nett`.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/nett --version")
  end
end
